__NUXT_JSONP__("/finanzas-publicas/noticias/alertan_por_mayor_deuda_del_gobierno_para_2026", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E){return {data:[{post:{slug:"alertan_por_mayor_deuda_del_gobierno_para_2026",title:"Alertan por mayor deuda del gobierno para 2026",date:"2025-09-23T17:11:31.161Z",img:"https:\u002F\u002Fucarecdn.com\u002Feca028e5-873e-4033-b8a5-85daf219ed73\u002F","img-alt":"Paquete económico 2026",autor:"Leonor Flores, El Universal",link:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Falertan-por-mayor-deuda-del-gobierno-para-2026\u002F",category:"finanzas-publicas",extracto:"Crece presión para las finanzas públicas a causa de programas sociales y Pemex, señalan; el costo de los pasivos rebasa al presupuesto destinado a la educación, salud e infraestructura",toc:[{id:m,depth:n,text:o},{id:p,depth:n,text:q}],body:{type:"root",children:[{type:b,tag:e,props:{},children:[{type:a,value:"Por segundo año consecutivo, el"},{type:b,tag:f,props:{href:r,rel:[g,h,i],target:j,title:r},children:[{type:a,value:s},{type:b,tag:c,props:{},children:[{type:a,value:"gobierno federal"}]},{type:a,value:s}]},{type:a,value:"solicitó al "},{type:b,tag:c,props:{},children:[{type:a,value:"Congreso de la Unión"}]},{type:a,value:" un mayor nivel de "},{type:b,tag:c,props:{},children:[{type:a,value:"endeudamiento"}]},{type:a,value:k}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"En el "},{type:b,tag:c,props:{},children:[{type:b,tag:f,props:{href:t,rel:[g,h,i],target:j,title:t},children:[{type:a,value:"Paquete Económico 2026"}]}]},{type:a,value:" se plantea un techo de endeudamiento interno de 1.7 billones de pesos, contra el nivel de 1.5 billones de pesos que "},{type:b,tag:c,props:{},children:[{type:a,value:"diputados"}]},{type:a,value:" y "},{type:b,tag:c,props:{},children:[{type:a,value:"senadores"}]},{type:a,value:" aprobaron para este año."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Al contrario, para el endeudamiento externo no se percibe la necesidad de "},{type:b,tag:c,props:{},children:[{type:a,value:"incrementarlo"}]},{type:a,value:", por lo que vuelven a pedir 15 mil 500 millones de dólares, como en 2025."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Igualmente, el "},{type:b,tag:c,props:{},children:[{type:a,value:"Gobierno de la Ciudad de México"}]},{type:a,value:" no prevé aumentar su deuda, al poner a consideración 3 mil 500 millones de pesos, ya que, por tener el respaldo del gobierno federal, el Congreso es el responsable de darle el visto bueno."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Analistas ponderaron que el mayor endeudamiento y, en consecuencia, un elevado "},{type:b,tag:c,props:{},children:[{type:a,value:"déficit fiscal"}]},{type:a,value:", es el reflejo de las presiones a las finanzas públicas, algo que nuevamente inquieta."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Una de las principales causas, señalaron, es el esfuerzo para sacar del atolladero a Petróleos Mexicanos ("},{type:b,tag:c,props:{},children:[{type:a,value:"Pemex"}]},{type:a,value:"), así como el aumento en el "},{type:b,tag:c,props:{},children:[{type:a,value:"gasto social"}]},{type:a,value:k}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:l},{type:b,tag:f,props:{href:u,rel:[g,h,i],target:j,title:u},children:[{type:a,value:"Con estímulo fiscal, el gobierno va por repatriación de capitales"}]}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Destaca el caso del programa Pensión Bienestar de Mujeres de 60 a 64 años, para el cual se solicitaron 56 mil 969 millones de pesos, desde poco más de 22 mil millones aprobados para este año."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Incluso, destacaron que el endeudamiento es similar al costo financiero por el "},{type:b,tag:c,props:{},children:[{type:a,value:"pago de intereses"}]},{type:a,value:", que se estima en 1.3 billones de pesos a enfrentar en 2026."}]},{type:a,value:d},{type:b,tag:v,props:{id:m},children:[{type:b,tag:f,props:{href:"#pemex-lastre",ariaHidden:w,tabIndex:x},children:[{type:b,tag:y,props:{className:[z,A]},children:[]}]},{type:a,value:o}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Para la directora de Finanzas Públicas de Ethos Innovación en Política Públicas, Dalia Toledo, en 2026 se verá un incremento en el endeudamiento porque están aumentando los recursos a tres programas sociales insignia de la actual administración: "},{type:b,tag:c,props:{},children:[{type:a,value:"Pensiones a Mujeres"}]},{type:a,value:" (+267%), "},{type:b,tag:c,props:{},children:[{type:a,value:"Salud Casa por Casa"}]},{type:a,value:" (+93%) y "},{type:b,tag:c,props:{},children:[{type:a,value:"Beca Rita Cetina"}]},{type:a,value:" (+58%)."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"También por una marcada tendencia en el gasto de la "},{type:b,tag:c,props:{},children:[{type:a,value:"Secretaría de Energía"}]},{type:a,value:" para apuntalar a Pemex con el plan anunciado recientemente. “Son esas dos cosas las que más están comprometiendo el gasto público y la deuda”, advirtió."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"De hecho, previó que quizá el endeudamiento sea mucho más alto de lo que se está considerando en el Paquete Económico 2026."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:l},{type:b,tag:f,props:{href:B,rel:[g,h,i],target:j,title:B},children:[{type:a,value:"Sheinbaum dice que dialoga con embajadores por aranceles de Paquete Económico; busca que no haya conflicto"}]}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"En entrevista con "},{type:b,tag:c,props:{},children:[{type:a,value:"EL UNIVERSAL,"}]},{type:a,value:" ponderó que, por lo general, rebasa lo que se plantea en los Criterios Generales de Política Económica ("},{type:b,tag:c,props:{},children:[{type:a,value:"CGPE"}]},{type:a,value:"), como se pudo constatar ahora para 2026."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Se aplicó un ajuste al alza al saldo de la deuda de 51.4% a 52.3% del Producto Interno Bruto ("},{type:b,tag:c,props:{},children:[{type:a,value:"PIB"}]},{type:a,value:") tan sólo para 2025, puntualizó."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"También sucedió con los precriterios para 2026, dijo, con una estimación inicial de 3.2% que se revisó a 4.1% del PIB en los CGPE."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:"Lee también"},{type:b,tag:f,props:{href:C,rel:[g,h,i],target:j,title:C},children:[{type:a,value:" “Vamos a resistir embates y presiones de los cabilderos”, señala presidente de la Comisión de Hacienda en Diputados"}]}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Esto es una presión para las finanzas, ya que “ocho de cada 10 pesos se destinan a gasto que el gobierno federal no puede dejar de pagar, y va creciendo”, sin incrementar más los "},{type:b,tag:c,props:{},children:[{type:a,value:"ingresos"}]},{type:a,value:k}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Es decir, 80% es gasto ineludible para pensiones, intereses de la deuda y Pemex, así como para estados y municipios, enfatizó."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Para el restante 20%, que es el margen que tiene el gobierno federal, se necesita “rascarle al monedero”, agregó, porque los "},{type:b,tag:c,props:{},children:[{type:a,value:"recursos adicionales"}]},{type:a,value:" se van a acabar y así no se puede controlar la deuda."}]},{type:a,value:d},{type:b,tag:v,props:{id:p},children:[{type:b,tag:f,props:{href:"#poco-espacio-fiscal",ariaHidden:w,tabIndex:x},children:[{type:b,tag:y,props:{className:[z,A]},children:[]}]},{type:a,value:q}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"La directora ejecutiva del Centro de Investigación Económica Presupuestaria ("},{type:b,tag:c,props:{},children:[{type:a,value:"CIEP"}]},{type:a,value:"), Alejandra Macías, ponderó que ese espacio fiscal equivale a 1.7% del PIB, un tercio de lo que se tenía en 2018."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"En la presentación del análisis del Paquete Económico, expresó que por eso el costo de la deuda debe alarmar, pues representa 4.1% del tamaño de la economía, lo que evidencia la necesidad de modificaciones de fondo al esquema tributario. “Si ya se empezó con una miscelánea (para 2026), hay que seguir con una "},{type:b,tag:c,props:{},children:[{type:a,value:"reforma fiscal"}]},{type:a,value:"”, estimó."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"Macías estableció que, si se está solicitando un mayor endeudamiento respecto al de este año, es reflejo de un escenario de presiones fiscales y limitaciones estructurales en el uso de recursos públicos."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:b,tag:c,props:{},children:[{type:a,value:l},{type:b,tag:f,props:{href:D,rel:[g,h,i],target:j,title:D},children:[{type:a,value:"Pese a gusano barrenador, gobierno recortó presupuesto para sanidad e inocuidad, critica Consejo Nacional Agropecuario"}]}]}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"El director de Investigación del CIEP, José Luis Clavellina, alertó que la deuda se encuentra en un nivel de 52% del PIB y tiene un costo de 4.1%. Es un gasto que representa mucho más de lo que se destina a educación, salud e infraestructura."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"“Sí es un nivel del que debemos empezar a preocuparnos, porque es igual al "},{type:b,tag:c,props:{},children:[{type:a,value:"costo financiero de la deuda"}]},{type:a,value:", y vamos a pedir prestado para pagar lo que debemos”, manifestó."}]},{type:a,value:d},{type:b,tag:e,props:{},children:[{type:a,value:"BBVA resaltó en un análisis que dicho costo pasará de 3.8% del PIB a 4.1%, lo que reducirá aún más el espacio fiscal. Por eso, dudó que en 2027 Pemex ya no vaya a requerir apoyo, tras la "},{type:b,tag:c,props:{},children:[{type:a,value:"línea presupuestal"}]},{type:a,value:" de 263 mil 500 millones de pesos que recibirá el próximo año."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Falertan_por_mayor_deuda_del_gobierno_para_2026",extension:".md",createdAt:E,updatedAt:E}}],fetch:{},mutations:[]}}("text","element","strong","\n","p","a","nofollow","noopener","noreferrer","_blank",".","Lee también ","pemex-lastre",2,"Pemex: lastre","poco-espacio-fiscal","Poco espacio fiscal","https:\u002F\u002Fwww.eluniversal.com.mx\u002Fnacion\u002Fsemar-gobierno-federal-mantiene-politica-de-cero-tolerancia-a-la-corrupcion-se-defiende-prestigio-de-la-marina\u002F"," ","https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fpaquete-economico-refleja-estabilidad-para-2026-canaco-cdmx-ve-necesaria-mas-claridad-sobre-gasto-en-seguridad-salud-y-servicios\u002F","https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fcon-estimulo-fiscal-el-gobierno-va-por-repatriacion-de-capitales\u002F","h2","true",-1,"span","icon","icon-link","https:\u002F\u002Fwww.eluniversal.com.mx\u002Fnacion\u002Fsheinbaum-dice-que-dialoga-con-embajadores-por-aranceles-de-paquete-economico-busca-que-no-haya-conflicto\u002F","https:\u002F\u002Fwww.eluniversal.com.mx\u002Fnacion\u002Fcomision-de-hacienda-en-diputados\u002F","https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fpese-a-gusano-barrenador-gobierno-recorto-presupuesto-para-sanidad-e-inocuidad-critica-consejo-nacional-agropecuario\u002F","2025-11-25T01:24:03.259Z")));